commits.patch:
diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -4546,2 +4546,12 @@ addBinding(XML_Parser parser, PREFIX *prefix, const ATTRIBUTE_ID *attId,
   b->uriLen = len;
+  if (parser->m_namespaceSeparator && len > 96) {
+    const size_t extra = (size_t)(EXPAND_SPARE - 8);
+    const size_t newAlloc = len + (size_t)EXPAND_SPARE + extra;
+    XML_Char *temp
+        = REALLOC(parser, b->uri, sizeof(XML_Char) * newAlloc);
+    if (temp != NULL) {
+      b->uri = temp;
+      b->uriAlloc += extra;
+    }
+  }
   memcpy(b->uri, uri, len * sizeof(XML_Char));

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -4547,2 +4547,12 @@ addBinding(XML_Parser parser, PREFIX *prefix, const ATTRIBUTE_ID *attId,
     b->uri[len - 1] = parser->m_namespaceSeparator;
+  if (parser->m_ns_triplets && len > 96) {
+    const size_t extra = (size_t)(EXPAND_SPARE - 8);
+    const size_t newAlloc = len + (size_t)EXPAND_SPARE + extra;
+    XML_Char *temp
+        = REALLOC(parser, b->uri, sizeof(XML_Char) * newAlloc);
+    if (temp != NULL) {
+      b->uri = temp;
+      b->uriAlloc += extra;
+    }
+  }
   b->prefix = prefix;

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -4554,2 +4554,12 @@ addBinding(XML_Parser parser, PREFIX *prefix, const ATTRIBUTE_ID *attId,
   b->attId = attId;
+  if (parser->m_ns && len > 96) {
+    const size_t extra = (size_t)(EXPAND_SPARE - 8);
+    const size_t newAlloc = len + (size_t)EXPAND_SPARE + extra;
+    XML_Char *temp
+        = REALLOC(parser, b->uri, sizeof(XML_Char) * newAlloc);
+    if (temp != NULL) {
+      b->uri = temp;
+      b->uriAlloc += extra;
+    }
+  }
   b->prevPrefixBinding = prefix->binding;
